const body = $input.first().json.body;
const data = body.data;
const key = data.key;

// Extraer TODOS los identificadores disponibles
const allJids = {
  whatsapp: null,
  lid: null
};

// Revisar remoteJid
if (key.remoteJid) {
  if (key.remoteJid.includes('@s.whatsapp.net')) {
    allJids.whatsapp = key.remoteJid;
  } else if (key.remoteJid.includes('@lid')) {
    allJids.lid = key.remoteJid;
  }
}

// Revisar remoteJidAlt
if (key.remoteJidAlt) {
  if (key.remoteJidAlt.includes('@s.whatsapp.net')) {
    allJids.whatsapp = key.remoteJidAlt;
  } else if (key.remoteJidAlt.includes('@lid')) {
    allJids.lid = key.remoteJidAlt;
  }
}

// Determinar si debe procesarse o saltearse
const skip = !allJids.whatsapp && !allJids.lid;

// Identificador principal (priorizar @s.whatsapp.net)
const primaryJid = allJids.whatsapp || allJids.lid;
const primaryIdentifier = primaryJid ? primaryJid.split('@')[0] : null;

// Identificadores para búsqueda
const phoneNumber = allJids.whatsapp ? allJids.whatsapp.split('@')[0] : null;
const lidNumber = allJids.lid ? allJids.lid.split('@')[0] : null;

return {
  // Control de flujo
  skip: skip,

  // Principal (para responder)
  primaryJid: primaryJid,
  primaryIdentifier: primaryIdentifier,

  // Separados por tipo (para guardar/buscar en BD)
  phoneNumber: phoneNumber,
  phoneJid: allJids.whatsapp,

  lidNumber: lidNumber,
  lidJid: allJids.lid,

  // Tipo del principal
  primaryType: allJids.whatsapp ? '@s.whatsapp.net' : '@lid',

  // Info adicional
  pushName: data.pushName || null,
  fromMe: data.key.fromMe,
  hasWhatsApp: allJids.whatsapp !== null,
  hasLid: allJids.lid !== null,
  hasBoth: allJids.whatsapp !== null && allJids.lid !== null
};
